<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import AppIcon from '../components/AppIcon.vue';
import type { DetailResult,HomeResult,SourceConfig,VideoCard } from '@free-new-desk/contracts';
import { isVodFavorite,toggleVodFavorite } from '../favorites';
import { emitPlaybackStage } from '../playback-events';
import { usePageStateStore } from '../stores/page-state';
import { usePlaybackSessionStore } from '../stores/playback-session';
import { useToastStore } from '../stores/toast';
import {useSourceChanges} from '../source-changes';
useSourceChanges(refreshSourceList);
let sourceListGeneration=0;
async function refreshSourceList(){const generation=++sourceListGeneration;try{const values=await window.desktop.source.list();if(generation!==sourceListGeneration)return;const previous=sources.value.find(item=>item.id===sourceId.value);sources.value=values;if(!enabledSources.value.some(item=>item.id===sourceId.value))sourceId.value=enabledSources.value[0]?.id??'';const current=sources.value.find(item=>item.id===sourceId.value);if(JSON.stringify(previous)!==JSON.stringify(current)){if(sourceId.value)await loadSource(false);else{browseGeneration++;detailGeneration++;items.value=[];homeMeta.value=null;detail.value=null;loading.value=false;}}}catch(value){error.value=value instanceof Error?value.message:String(value);}}

const router=useRouter();const route=useRoute();const pageState=usePageStateStore();const playbackSession=usePlaybackSessionStore();
const toast=useToastStore();
const preparingId=ref('');
const playBusy=ref(false);
const showFilters=ref(false);const contextItem=ref<VideoCard|null>(null);const contextX=ref(0);const contextY=ref(0);const sources=ref<SourceConfig[]>([]);const sourceId=ref('');const items=ref<VideoCard[]>([]);const homeMeta=ref<HomeResult|null>(null);const detail=ref<DetailResult|null>(null);const favorite=ref(false);const keyword=ref('');const loading=ref(false);const error=ref('');const categoryId=ref('');const manualCategoryId=ref('');const categoryPage=ref(1);const categoryHasMore=ref(false);const totalPages=ref(1);const totalItems=ref<number|null>(null);const pageInput=ref(1);const filterValues=ref<Record<string,string>>({});const mode=ref<'home'|'category'|'search'>('home');const viewMode=ref<'grid'|'list'>(localStorage.getItem('vod.viewMode')==='list'?'list':'grid');const selectedFlag=ref('');const nowPlaying=ref<{videoId:string;episodeId:string}|null>(null);const sortMode=ref<'default'|'rating'|'newest'|'popular'|'name'>('default');const episodePage=ref(1);const fixedCategories=['全部','电影','电视剧','综艺','动漫','纪录片','短剧'];let searchTimer:ReturnType<typeof setTimeout>|undefined;
function setViewMode(next:'grid'|'list'){viewMode.value=next;localStorage.setItem('vod.viewMode',next);}
interface VodSession{categoryId?:string;page?:number;filters?:Record<string,string>;sortMode?:typeof sortMode.value;showFilters?:boolean;detailId?:string|undefined;}
interface PendingVodPlayback{requestId:string;createdAt:number;request:{sourceId:string;videoId:string;videoName:string;flag:string;episodeId:string;episodeName:string;poster?:string;episodeListJson:string;};sourceName:string;}
interface VodPageSnapshot{sources:SourceConfig[];sourceId:string;items:VideoCard[];homeMeta:HomeResult|null;detail:DetailResult|null;favorite:boolean;categoryId:string;manualCategoryId:string;categoryPage:number;categoryHasMore:boolean;totalPages:number;totalItems:number|null;pageInput:number;filterValues:Record<string,string>;mode:'home'|'category'|'search';sortMode:'default'|'rating'|'newest'|'popular'|'name';episodePage:number;selectedFlag:string;showFilters:boolean;}
function sessionKey(id=sourceId.value){return`vod.session.${id}`;}
function readSession(id:string):VodSession{try{const value=JSON.parse(localStorage.getItem(sessionKey(id))??'{}') as VodSession;return value&&typeof value==='object'?value:{};}catch{return{};}}
function saveSession(extra:Partial<VodSession>={}){if(!sourceId.value)return;const value:VodSession={categoryId:categoryId.value,page:categoryPage.value,filters:{...filterValues.value},sortMode:sortMode.value,showFilters:showFilters.value,...extra};localStorage.setItem(sessionKey(),JSON.stringify(value));localStorage.setItem('vod.sourceId',sourceId.value);}
function savePendingPlayback(value:PendingVodPlayback){localStorage.setItem('vod.pendingPlayback',JSON.stringify(value));}
function clearPendingPlayback(requestId:string){try{const pending=JSON.parse(localStorage.getItem('vod.pendingPlayback')??'null') as Partial<PendingVodPlayback>|null;if(pending?.requestId===requestId)localStorage.removeItem('vod.pendingPlayback');}catch{localStorage.removeItem('vod.pendingPlayback');}}
const sortedItems=computed(()=>{if(findSortOption(sortMode.value))return items.value;return items.value.map((item,index)=>({item,index})).sort((a,b)=>{let order=0;if(sortMode.value==='name')order=a.item.name.localeCompare(b.item.name);else if(sortMode.value==='rating')order=(Number(b.item.rating)||0)-(Number(a.item.rating)||0);else if(sortMode.value==='popular')order=(Number(b.item.remark?.match(/\d+/)?.[0])||0)-(Number(a.item.remark?.match(/\d+/)?.[0])||0);return order||a.index-b.index;}).map(entry=>entry.item);});const missingCategories=computed(()=>fixedCategories.slice(1).filter(name=>!categories.value.some(item=>item.name.includes(name))));const pagedEpisodes=computed(()=>visibleEpisodes.value.slice((episodePage.value-1)*20,episodePage.value*20));const episodePages=computed(()=>Math.max(1,Math.ceil(visibleEpisodes.value.length/20)));const enabledSources=computed(()=>sources.value.filter(source=>source.enabled));const selectedSource=computed(()=>sources.value.find(source=>source.id===sourceId.value));const categories=computed(()=>homeMeta.value?.categories??[]);const activeFilters=computed(()=>categoryId.value?(homeMeta.value?.filters?.[categoryId.value]??[]):[]);const displayFilters=computed(()=>{const values=[...activeFilters.value];const fallback=[{key:'class',name:'类型',options:['剧情','喜剧','动作','爱情','科幻','悬疑','惊悚','犯罪','冒险','奇幻','动画','纪录片'].map(value=>({label:value,value}))},{key:'area',name:'地区',options:['中国大陆','中国香港','中国台湾','美国','英国','法国','日本','韩国','印度','泰国','其他'].map(value=>({label:value,value}))},{key:'year',name:'年份',options:['2026','2025','2024','2023','2022','2021','2020','2010年代','2000年代','更早'].map(value=>({label:value,value}))}];for(const item of fallback)if(!values.some(value=>value.key===item.key))values.push(item);return values;});const episodeFlags=computed(()=>[...new Set(detail.value?.episodes.map(item=>item.flag)??[])]);const visibleEpisodes=computed(()=>detail.value?.episodes.filter(item=>!selectedFlag.value||item.flag===selectedFlag.value)??[]);const firstPageButton=computed(()=>pageButtons.value[0]??1);const lastPageButton=computed(()=>pageButtons.value.at(-1)??1);const pageButtons=computed(()=>{const start=Math.max(1,categoryPage.value-2);const end=Math.min(totalPages.value,categoryPage.value+2);return Array.from({length:Math.max(0,end-start+1)},(_,index)=>start+index);});const nextPageAvailable=computed(()=>mode.value==='category'&&items.value.length>0&&(categoryHasMore.value||categoryPage.value<totalPages.value));const nextPageLabel=computed(()=>nextPageAvailable.value?`加载下一页（第 ${categoryPage.value+1} 页）`:`已到最后一页（第 ${categoryPage.value} 页）`);
watch(visibleEpisodes,()=>{episodePage.value=Math.min(Math.max(1,episodePage.value),episodePages.value);});
function selectEpisodeFlag(flag:string){selectedFlag.value=flag;episodePage.value=1;}
let browseGeneration=0;let detailGeneration=0;
type BrowseRequest={sourceId:string;generation:number};
function currentBrowse(request:BrowseRequest){return request.sourceId===sourceId.value&&request.generation===browseGeneration;}
function clearDetail(persist:boolean|MouseEvent=true){detailGeneration+=1;detail.value=null;favorite.value=false;selectedFlag.value='';episodePage.value=1;if(persist===true)saveSession({detailId:undefined});}function resetCategory(){categoryId.value='';manualCategoryId.value='';categoryPage.value=1;pageInput.value=1;categoryHasMore.value=false;totalPages.value=1;totalItems.value=null;filterValues.value={};}
async function loadHome(force=false){
  if(!sourceId.value)return;const request={sourceId:sourceId.value,generation:++browseGeneration};
  loading.value=true;error.value='';clearDetail(false);resetCategory();mode.value='home';
  try{const result=await window.desktop.source.home(request.sourceId,force);if(!currentBrowse(request))return;homeMeta.value=result;items.value=result.items;saveSession({detailId:detail.value?.id});void router.replace({query:{source:request.sourceId}});}
  catch(value){if(currentBrowse(request)){error.value=value instanceof Error?value.message:String(value);items.value=[];homeMeta.value=null;}}
  finally{if(currentBrowse(request))loading.value=false;}
 }
async function loadCategory(page=1,force=false,parent?:BrowseRequest){
  if(!sourceId.value||!categoryId.value)return;
  const request=parent??{sourceId:sourceId.value,generation:++browseGeneration};if(!currentBrowse(request))return;
  const category=categoryId.value,filtersSnapshot={...filterValues.value};loading.value=true;error.value='';if(!parent)clearDetail(false);mode.value='category';
  try{const entries=Object.entries(filtersSnapshot).filter(([,value])=>value!=='');let combinations:Array<Record<string,string>>=[{}];for(const [key,value]of entries){const options=value.split(',').filter(Boolean);combinations=combinations.flatMap(base=>options.map(option=>({...base,[key]:option}))).slice(0,20);}
    const results=await Promise.all((combinations.length?combinations:[{}]).map(filters=>window.desktop.source.category(request.sourceId,category,Math.max(1,page),filters,force)));
    if(!currentBrowse(request))return;
    const result={...results[0]!,items:[...new Map(results.flatMap(value=>value.items).map(item=>[item.id,item])).values()],hasMore:results.some(value=>value.hasMore),totalPages:Math.max(...results.map(value=>value.totalPages??value.page)),totalItems:results.length===1?results[0]?.totalItems:undefined};
    items.value=result.items;categoryPage.value=result.page;pageInput.value=result.page;categoryHasMore.value=result.hasMore;totalPages.value=Math.max(1,result.totalPages??(result.hasMore?result.page+1:result.page));totalItems.value=result.totalItems??null;saveSession({detailId:detail.value?.id});void router.replace({query:{source:request.sourceId,category,page:String(result.page)}});
  }catch(value){if(currentBrowse(request)){error.value=value instanceof Error?value.message:String(value);items.value=[];}}
  finally{if(currentBrowse(request))loading.value=false;}
 }
function toggleFilter(key:string,value:string){const current=new Set((filterValues.value[key]??'').split(',').filter(Boolean));current.has(value)?current.delete(value):current.add(value);filterValues.value[key]=[...current].join(',');void applyFilters();}
async function selectCategory(id:string){categoryId.value=id;manualCategoryId.value=id;categoryPage.value=1;pageInput.value=1;filterValues.value={};await loadCategory(1);}async function openManualCategory(){const id=manualCategoryId.value.trim();if(!id)return;categoryId.value=id;filterValues.value={};await loadCategory(1);}async function applyFilters(){await loadCategory(1);}async function jumpPage(){const requested=Math.floor(pageInput.value||1);if(requested<1||requested>totalPages.value){error.value=`页码必须在 1–${totalPages.value} 之间`;return;}await loadCategory(requested);}
async function toggleFiltersPanel(){const next=!showFilters.value;showFilters.value=next;if(next&&!categoryId.value&&categories.value.length){await selectCategory(categories.value[0]!.id);showFilters.value=true;}saveSession();}
function scheduleSearch(){if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(keyword.value.trim())void router.push({path:'/search',query:{q:keyword.value.trim()}});},300);}
async function search(){const value=keyword.value.trim();if(!value)return;await router.push({path:'/search',query:{q:value}});}
async function loadSource(force=false){
  if(!sourceId.value)return;const request={sourceId:sourceId.value,generation:++browseGeneration};
  localStorage.setItem('vod.sourceId',request.sourceId);const saved=readSession(request.sourceId);clearDetail(false);const restoreGeneration=detailGeneration;items.value=[];homeMeta.value=null;loading.value=true;error.value='';
  try{const home=await window.desktop.source.home(request.sourceId,force);if(!currentBrowse(request))return;
    homeMeta.value=home;showFilters.value=Boolean(saved.showFilters);sortMode.value=saved.sortMode??'default';categoryId.value=saved.categoryId??'';manualCategoryId.value=categoryId.value;filterValues.value=saved.filters??{};
    if(categoryId.value)await loadCategory(Math.max(1,saved.page??1),force,request);else{mode.value='home';items.value=home.items;categoryPage.value=1;pageInput.value=1;totalItems.value=null;categoryHasMore.value=false;totalPages.value=1;}
    if(!currentBrowse(request)||detailGeneration!==restoreGeneration)return;
    if(saved.detailId)await openVideo({id:saved.detailId,name:saved.detailId} as VideoCard,force);else saveSession({detailId:undefined});
  }catch(value){if(currentBrowse(request)){error.value=value instanceof Error?value.message:String(value);items.value=[];homeMeta.value=null;}}
  finally{if(currentBrowse(request))loading.value=false;}
 }
async function changeSource(){await loadSource(false);}
async function refreshSource(){await loadSource(true);}
async function openVideo(item:VideoCard,force=false){
  const request=++detailGeneration,source=sourceId.value;const current=()=>request===detailGeneration&&source===sourceId.value;
  detail.value=null;favorite.value=false;error.value='';
  try{const result=await window.desktop.source.detail(source,[item.id],force);if(!current())return;
    detail.value=result;selectedFlag.value=result.episodes[0]?.flag??'';episodePage.value=1;
    const selected=await isVodFavorite(source,result.id);if(!current())return;favorite.value=selected;saveSession({detailId:result.id});
  }catch(value){if(current())error.value=value instanceof Error?value.message:String(value);}
 }
function findSortOption(mode:typeof sortMode.value){const filter=activeFilters.value.find(item=>/sort|order|排序|按/.test(`${item.key} ${item.name}`.toLowerCase()));if(!filter)return null;const patterns={rating:/评分|rating|score/i,newest:/最新|时间|new|time|date/i,popular:/热门|热度|播放|hits|popular/i,name:/名称|name/i};const option=mode==='default'?undefined:filter.options.find(item=>patterns[mode].test(`${item.label} ${item.value}`));return option?{filter,option}:null;}
async function changeSort(){if(sortMode.value==='default'){saveSession();return;}const remote=findSortOption(sortMode.value);if(remote&&categoryId.value){filterValues.value[remote.filter.key]=remote.option.value;await loadCategory(1);return;}const supported=sortMode.value==='name'||(sortMode.value==='rating'&&items.value.some(item=>item.rating))||(sortMode.value==='popular'&&items.value.some(item=>/\d/.test(item.remark??'')));if(!supported){const label={rating:'评分',newest:'上架时间',popular:'播放量',name:'名称'}[sortMode.value];error.value=`当前来源未提供${label}排序字段，已保持来源默认顺序。`;sortMode.value='default';}saveSession();}
async function toggleFavorite(){if(!detail.value||!selectedSource.value)return;const request=detailGeneration,source=sourceId.value,item=detail.value;try{const result=await toggleVodFavorite(source,selectedSource.value.name,item);if(request===detailGeneration&&source===sourceId.value&&detail.value===item)favorite.value=result;}catch(value){if(request===detailGeneration&&source===sourceId.value)error.value=value instanceof Error?value.message:String(value);}}
async function play(flag:string,episodeId:string,episodeName:string){
  if(!detail.value||playBusy.value)return;
  playBusy.value=true;
  error.value='';
  const request={sourceId:sourceId.value,videoId:detail.value.id,videoName:detail.value.name,flag,episodeId,episodeName,...(detail.value.poster?{poster:detail.value.poster}:{}),episodeListJson:JSON.stringify(detail.value.episodes)};
  const pendingRequestId=crypto.randomUUID();
  savePendingPlayback({requestId:pendingRequestId,createdAt:Date.now(),request,sourceName:selectedSource.value?.name??sourceId.value});
  playbackSession.begin({kind:'vod',requestId:pendingRequestId,sourceId:sourceId.value,channelId:'',routeIndex:null,routeCount:0,fullscreen:false,pip:false,lastReason:'play'});
  nowPlaying.value={videoId:detail.value.id,episodeId};
  localStorage.setItem('vod.nowPlaying',JSON.stringify(nowPlaying.value));
  emitPlaybackStage('source-resolving','正在获取点播线路…');
  void window.desktop.playback.play(request).then(()=>{clearPendingPlayback(pendingRequestId);emitPlaybackStage('playing','媒体已打开');}).catch(value=>{const message=value instanceof Error?value.message:String(value);emitPlaybackStage('failed','播放失败',message);toast.error('播放失败',message);}).finally(()=>{playBusy.value=false;});
const navigationStarted=performance.now();
  await router.push('/player');
  const navigationMs=performance.now()-navigationStarted;
  void window.desktop.diagnostics.recordPerformance('playbackNavigationMs',navigationMs).catch(()=>false);
  if(window.desktop.app.isUiSmoke()&&navigationMs>150)throw new Error(`Playback navigation exceeded 150ms budget: ${navigationMs.toFixed(1)}ms`);
  }
async function openAndPlay(item:VideoCard){if(preparingId.value)return;preparingId.value=item.id;toast.info(`正在准备播放《${item.name}》…`);try{await openVideo(item);await playFirst();}finally{preparingId.value='';}}
function openContext(event:MouseEvent,item:VideoCard){contextItem.value=item;contextX.value=event.clientX;contextY.value=event.clientY;}
async function contextAction(action:'favorite'|'copy'|'play'|'window'){const item=contextItem.value;contextItem.value=null;if(!item)return;if(action==='copy')await window.desktop.app.action({copy:item.name});else if(action==='play')await openAndPlay(item);else if(action==='favorite'){await openVideo(item);await toggleFavorite();}else await window.desktop.app.openRoute(`/vod?source=${encodeURIComponent(sourceId.value)}&video=${encodeURIComponent(item.id)}`);}
function closeTransient(event:KeyboardEvent){if(event.key==='Escape'){showFilters.value=false;contextItem.value=null;clearDetail();}}
async function playFirst(){const episode=visibleEpisodes.value[0]??detail.value?.episodes[0];if(episode)await play(episode.flag,episode.id,episode.name);}
onMounted(async()=>{window.addEventListener('keydown',closeTransient);try{const parsed=JSON.parse(localStorage.getItem('vod.nowPlaying')??'null') as {videoId?:string;episodeId?:string}|null;if(parsed&&typeof parsed.videoId==='string'&&typeof parsed.episodeId==='string')nowPlaying.value={videoId:parsed.videoId,episodeId:parsed.episodeId};}catch{nowPlaying.value=null;}const cached=pageState.read<VodPageSnapshot>('vod');if(cached&&!route.query.source&&!route.query.category&&!route.query.video){const v=cached.value;sources.value=v.sources;sourceId.value=v.sourceId;items.value=v.items;homeMeta.value=v.homeMeta;detail.value=v.detail;favorite.value=v.favorite;categoryId.value=v.categoryId;manualCategoryId.value=v.manualCategoryId;categoryPage.value=v.categoryPage;categoryHasMore.value=v.categoryHasMore;totalPages.value=v.totalPages;totalItems.value=v.totalItems;pageInput.value=v.pageInput;filterValues.value={...v.filterValues};mode.value=v.mode;sortMode.value=v.sortMode;episodePage.value=v.episodePage;selectedFlag.value=v.selectedFlag;showFilters.value=v.showFilters;await refreshSourceList();return;}const listGeneration=++sourceListGeneration;const sourceValues=await window.desktop.source.list();if(listGeneration!==sourceListGeneration)return;sources.value=sourceValues;const routeSource=typeof route.query.source==='string'?route.query.source:'';const savedSource=localStorage.getItem('vod.sourceId')??'';sourceId.value=[routeSource,savedSource].find(id=>enabledSources.value.some(item=>item.id===id))??enabledSources.value[0]?.id??'';if(sourceId.value){if(typeof route.query.category==='string'){const saved=readSession(sourceId.value);localStorage.setItem(sessionKey(sourceId.value),JSON.stringify({...saved,categoryId:route.query.category,page:Number(route.query.page)||1,detailId:typeof route.query.video==='string'?route.query.video:saved.detailId}));}await loadSource(false);if(typeof route.query.video==='string'&&detail.value?.id!==route.query.video)await openVideo({id:route.query.video,name:route.query.video} as VideoCard);}});
onBeforeUnmount(()=>{sourceListGeneration++;browseGeneration+=1;detailGeneration+=1;pageState.save<VodPageSnapshot>('vod',{sources:[...sources.value],sourceId:sourceId.value,items:[...items.value],homeMeta:homeMeta.value,detail:detail.value,favorite:favorite.value,categoryId:categoryId.value,manualCategoryId:manualCategoryId.value,categoryPage:categoryPage.value,categoryHasMore:categoryHasMore.value,totalPages:totalPages.value,totalItems:totalItems.value,pageInput:pageInput.value,filterValues:{...filterValues.value},mode:mode.value,sortMode:sortMode.value,episodePage:episodePage.value,selectedFlag:selectedFlag.value,showFilters:showFilters.value});window.removeEventListener('keydown',closeTransient);if(searchTimer)clearTimeout(searchTimer);});
</script>

<template>
  <section class="page vod-page">
    <div class="page-heading split vod-heading"><div><h1>点播</h1></div><div class="toolbar-group"><select v-model="sourceId" class="source-select" @change="changeSource"><option disabled value="">选择来源</option><option v-for="source in enabledSources" :key="source.id" :value="source.id">{{source.name}}</option></select><button class="secondary-button" :disabled="loading||!sourceId" @click="refreshSource">刷新来源</button><div class="search-box"><span><AppIcon name="nav-search" :size="16"/></span><input v-model="keyword" maxlength="100" placeholder="搜索影片、演员、导演" data-search-input @input="scheduleSearch" @keyup.enter="search"/></div><button class="secondary-button" @click="search">搜索</button></div></div>

    <div class="vod-workspace">
      <div class="vod-main">
        <div class="section-tabs"><button :class="{active:mode==='home'&&!showFilters}" @click="showFilters=false;loadHome()">分类</button><button :class="{active:showFilters}" @click="toggleFiltersPanel">筛选</button><button :class="{active:mode==='home'&&!categoryId}" @click="showFilters=false;loadHome()">推荐</button><RouterLink to="/history">最近观看</RouterLink></div>
        <div v-if="sourceId" class="category-strip"><button class="chip" :class="{active:!categoryId&&mode==='home'}" @click="loadHome()">全部</button><button v-for="category in categories" :key="category.id" class="chip" :class="{active:categoryId===category.id}" @click="selectCategory(category.id)">{{category.name}}</button><button v-for="name in missingCategories" :key="'missing-'+name" class="chip" disabled :title="`当前来源未声明${name}分类`">{{name}}</button><template v-if="categories.length===0"><input v-model="manualCategoryId" class="inline-category" placeholder="分类 ID" @keyup.enter="openManualCategory"/><button class="chip" :disabled="!manualCategoryId.trim()" @click="openManualCategory">打开分类</button></template></div>
        <div v-if="showFilters&&!categoryId" class="filter-hint">当前来源尚未返回可用分类。请先点“刷新来源”；如果来源支持 CMS 分类，软件会自动尝试兼容的分类元数据接口。</div>
        <div v-if="showFilters&&categoryId&&displayFilters.length" class="filter-stack filter-drawer"><div v-for="filter in displayFilters" :key="filter.key" class="filter-row"><span>{{filter.name}}</span><button class="filter-option" :class="{active:!filterValues[filter.key]}" @click="filterValues[filter.key]='';applyFilters()">全部</button><button v-for="option in filter.options" :key="option.value" class="filter-option" :class="{active:(filterValues[filter.key]??'').split(',').includes(option.value)}" @click="toggleFilter(filter.key,option.value)">{{option.label}}</button></div></div>

        <p v-if="error" class="error-banner">{{error}}</p>
        <div v-if="!sourceId" class="empty-state"><div class="empty-icon">＋</div><h3>没有已启用来源</h3><p>前往“来源”导入 TVBox/FongMi 配置。</p></div>
        <div v-else-if="loading" class="loading-panel skeleton-wall" aria-busy="true"><span class="sr-only">正在加载内容…</span><div v-for="n in 8" :key="n" class="skeleton-card poster-skeleton"><span class="skeleton poster-block"/><span class="skeleton" style="width:70%;height:13px"/><span class="skeleton" style="width:45%;height:11px"/></div></div>
        <template v-else>
          <div class="results-bar"><span>共 {{totalItems??items.length}} 个结果</span><select v-model="sortMode" aria-label="点播排序" @change="changeSort"><option value="default">来源默认</option><option value="rating">评分最高</option><option value="newest">最新上架</option><option value="popular">最多播放</option><option value="name">名称</option></select><div v-if="mode==='category'" class="pagination numeric-pages"><button :disabled="categoryPage<=1" @click="loadCategory(categoryPage-1)">‹</button><span v-if="firstPageButton>1">…</span><button v-for="page in pageButtons" :key="page" :class="{active:page===categoryPage}" @click="loadCategory(page)">{{page}}</button><span v-if="lastPageButton<totalPages">…</span><button :disabled="!nextPageAvailable" @click="loadCategory(categoryPage+1)">›</button><input v-model.number="pageInput" type="number" min="1" aria-label="跳转页码" :max="totalPages" @keyup.enter="jumpPage"/><button @click="jumpPage">跳转</button></div><div class="view-toggle"><button :class="{active:viewMode==='grid'}" title="网格" @click="setViewMode('grid')"><AppIcon name="action-grid" :size="15"/></button><button :class="{active:viewMode==='list'}" title="列表" @click="setViewMode('list')"><AppIcon name="action-list" :size="15"/></button></div></div>
          <div v-if="items.length" :class="viewMode==='grid'?'poster-grid cinematic':'vod-list-view'"><button v-for="item in sortedItems" :key="item.id" class="poster-card" :class="{selected:detail?.id===item.id,list:viewMode==='list',preparing:preparingId===item.id}" :aria-busy="preparingId===item.id" @click="openVideo(item)" @dblclick="openAndPlay(item)" @contextmenu.prevent="openContext($event,item)"><div class="poster-art"><img v-if="item.poster" :src="item.poster" :alt="item.name+' 海报'" loading="lazy"/><div v-else class="poster-placeholder"><AppIcon name="player-play" :size="22"/></div><span v-if="item.rating" class="score-badge"><AppIcon name="nav-star-filled" :size="11"/> {{item.rating}}</span><span v-if="item.remark" class="poster-badge">{{item.remark}}</span><span class="poster-hover-actions"><span class="hover-play" role="button" tabindex="-1" :aria-label="`立即播放 ${item.name}`" @click.stop="openAndPlay(item)"><AppIcon name="player-play" :size="16"/></span><span class="hover-act" role="button" tabindex="-1" aria-label="更多操作" @click.stop="openContext($event,item)"><AppIcon name="action-more" :size="16"/></span></span></div><div class="poster-copy"><strong>{{item.name}}</strong><small v-if="viewMode==='list'">{{item.remark||'点击查看详情'}}</small></div></button></div>
          <button v-if="mode==='category'&&items.length" class="secondary-button load-next-page" :disabled="!nextPageAvailable" @click="loadCategory(categoryPage+1)">{{nextPageLabel}}</button><div v-if="items.length===0" class="empty-state compact"><h3>当前来源没有返回内容</h3><p>尝试切换分类、筛选条件或搜索。</p></div><div v-if="contextItem" class="vod-context-menu" :style="{left:contextX+'px',top:contextY+'px'}"><button @click="contextAction('play')">立即播放</button><button @click="contextAction('favorite')">收藏 / 取消收藏</button><button @click="contextAction('copy')">复制标题</button><button @click="contextAction('window')">新窗口打开</button></div>
        </template>
      </div>

      <aside class="vod-detail detail-rail">
        <template v-if="detail">
          <button class="rail-close" aria-label="关闭详情" title="关闭详情" @click="clearDetail"><AppIcon name="action-close" :size="16"/></button><img v-if="detail.poster" class="detail-poster" :src="detail.poster" :alt="detail.name+' 海报'"/><div v-else class="detail-poster placeholder"><AppIcon name="player-play" :size="22"/></div><div class="title-score"><h2>{{detail.name}}</h2><b v-if="detail.rating"><AppIcon name="nav-star-filled" :size="12"/> {{detail.rating}}</b></div><small>{{detail.remark}}</small><div v-if="detail.year||detail.area||detail.type" class="detail-meta"><span v-if="detail.year">{{detail.year}}</span><span v-if="detail.area">{{detail.area}}</span><span v-if="detail.type">{{detail.type}}</span></div><p>{{detail.description||'该来源未提供简介。'}}</p><div v-if="detail.director||detail.actors?.length" class="people-meta"><p v-if="detail.director"><b>导演</b>{{detail.director}}</p><p v-if="detail.actors?.length"><b>演员</b><span class="actor-list"><i v-for="actor in detail.actors" :key="actor"><em>{{actor.slice(0,1)}}</em>{{actor}}</i></span></p></div><button class="primary-button wide" :disabled="detail.episodes.length===0||playBusy" :aria-busy="playBusy" @click="playFirst"><AppIcon v-if="!playBusy" name="player-play" :size="15"/>{{playBusy?'正在准备播放…':' 立即播放'}}</button><button class="secondary-button wide" @click="toggleFavorite"><AppIcon :name="favorite?'nav-star-filled':'nav-star'" :size="15"/>{{favorite?' 已收藏':' 收藏'}}</button><div v-if="episodeFlags.length>1" class="route-tabs"><strong>播放线路</strong><button v-for="flag in episodeFlags" :key="flag" :class="{active:selectedFlag===flag}" @click="selectEpisodeFlag(flag)">{{flag}}</button></div><div class="episode-heading"><strong>剧集列表</strong><span>{{visibleEpisodes.length}} 集</span></div><div class="episode-grid"><button v-for="(episode,index) in pagedEpisodes" :key="episode.flag+episode.id" :class="{'now-playing':nowPlaying&&nowPlaying.videoId===detail.id&&nowPlaying.episodeId===episode.id}" :title="`${episode.name||index+1}${nowPlaying&&nowPlaying.videoId===detail.id&&nowPlaying.episodeId===episode.id?'（当前正在播放）':''}`" @click="play(episode.flag,episode.id,episode.name)">{{episode.name||index+1}}</button></div><div v-if="episodePages>1" class="episode-pagination"><button :disabled="episodePage<=1" @click="episodePage--">上一组</button><span>{{episodePage}} / {{episodePages}}</span><button :disabled="episodePage>=episodePages" @click="episodePage++">下一组</button></div>
        </template>
        <div v-else class="detail-empty"><span><AppIcon name="player-play" :size="22"/></span><h3>选择一个条目</h3><p>影片详情、线路和剧集会显示在这里。</p></div>
      </aside>
    </div>
  </section>
</template>

